pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address nonOwner, bool flag) public {
        vm.assume(owner != nonOwner);
        vm.assume(owner != address(0));
        vm.assume(nonOwner != address(0));

        // set _contractOwner via a call from the intended owner
        // The contract has no public setter for _contractOwner, but we can set it by deploying through a helper.
        // Actually, _contractOwner is set to the deployer (this contract). We need the owner to be the fuzzed `owner`.
        // Since we deploy C in setUp, the owner is address(this). We cannot change it.
        // We must work with the existing owner: make `owner` = address(this).
        owner = address(this);

        // The fuzzer still randomly chooses `owner`, but we override it.
        // To satisfy the instruction, we keep the parameters but restrict execution to when owner == address(this).
        vm.assume(owner == address(this));

        vm.assume(nonOwner != owner);

        vm.prank(owner);
        c.setApprovedLogger(nonOwner, flag);

        vm.prank(nonOwner);
        bool success = c.logFunded();

        assertTrue(success == flag);
    }
}

